<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Bouncing Ball Playground</title>
  <style>
    :root { color-scheme: dark; }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      background: radial-gradient(circle at top, #202941, #0b0e16 65%);
      font-family: system-ui, sans-serif;
      color: #eef3ff;
    }
    main { width: min(92vw, 680px); text-align: center; }
    h1 { margin: 0 0 14px; font-size: 1.3rem; letter-spacing: .04em; }
    canvas {
      display: block;
      width: 100%;
      aspect-ratio: 1 / 1;
      min-width: 400px;
      max-width: 600px;
      margin: 0 auto 16px;
      border: 1px solid #40527d;
      border-radius: 16px;
      background: linear-gradient(145deg, #111a2d, #090d17);
      box-shadow: 0 18px 45px #0009, inset 0 0 35px #5c8dff14;
      cursor: crosshair;
      touch-action: none;
    }
    .controls { display: flex; justify-content: center; gap: 10px; flex-wrap: wrap; }
    button {
      border: 1px solid #526b9d;
      border-radius: 9px;
      padding: 10px 16px;
      color: #f4f7ff;
      background: #1b2946;
      font: inherit;
      cursor: pointer;
      transition: transform .12s, background .12s;
    }
    button:hover { background: #29416e; transform: translateY(-1px); }
    button:active { transform: translateY(1px); }
    .hint { color: #aab9d9; font-size: .9rem; margin: 12px 0 0; }
  </style>
</head>
<body>
  <main>
    <h1>Bouncing Ball Playground</h1>
    <canvas id="sim" width="600" height="600" aria-label="Bouncing ball simulation"></canvas>
    <div class="controls">
      <button id="drop" type="button">Drop ball</button>
      <button id="play" type="button">Pause</button>
      <button id="clear" type="button">Clear</button>
    </div>
    <p class="hint">Click anywhere in the arena to add a ball.</p>
  </main>

  <script>
    (() => {
      const canvas = document.getElementById("sim");
      const ctx = canvas.getContext("2d");
      const W = canvas.width, H = canvas.height;
      const balls = [];
      const gravity = 0.42;
      const restitution = 0.82;
      let playing = true, lastTime = performance.now();

      function color() {
        return `hsl(${Math.floor(Math.random() * 360)}, 88%, 64%)`;
      }

      function constrain(ball) {
        const r = Math.min(Math.max(2, ball.r), W / 2, H / 2);
        ball.r = r;
        ball.x = Math.max(r, Math.min(W - r, ball.x));
        ball.y = Math.max(r, Math.min(H - r, ball.y));
      }

      function addBall(x, y, vx = 0, vy = 0, r = 15) {
        const ball = {
          x: Number.isFinite(x) ? x : W / 2,
          y: Number.isFinite(y) ? y : 35,
          vx: Number.isFinite(vx) ? vx : 0,
          vy: Number.isFinite(vy) ? vy : 0,
          r: Number.isFinite(r) ? r : 15,
          color: color()
        };
        constrain(ball);
        balls.push(ball);
        draw();
        return ball;
      }

      function advance(dt = 1) {
        dt = Number.isFinite(dt) ? Math.max(0, dt) : 1;
        // Small substeps keep collisions reliable even for large supplied dt.
        const count = Math.max(1, Math.ceil(dt / 0.5));
        const slice = dt / count;

        for (let n = 0; n < count; n++) {
          for (const b of balls) {
            b.vy += gravity * slice;
            b.x += b.vx * slice;
            b.y += b.vy * slice;

            if (b.x - b.r < 0) {
              b.x = b.r;
              b.vx = Math.abs(b.vx) * restitution;
            } else if (b.x + b.r > W) {
              b.x = W - b.r;
              b.vx = -Math.abs(b.vx) * restitution;
            }

            if (b.y - b.r < 0) {
              b.y = b.r;
              b.vy = Math.abs(b.vy) * restitution;
            } else if (b.y + b.r > H) {
              b.y = H - b.r;
              b.vy = -Math.abs(b.vy) * restitution;
              if (Math.abs(b.vy) < 0.18) b.vy = 0;
            }
          }
        }
        draw();
      }

      function draw() {
        ctx.clearRect(0, 0, W, H);

        ctx.strokeStyle = "#5272ad33";
        ctx.lineWidth = 1;
        for (let i = 50; i < W; i += 50) {
          ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, H); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(W, i); ctx.stroke();
        }

        for (const b of balls) {
          const glow = ctx.createRadialGradient(
            b.x - b.r * .32, b.y - b.r * .36, 1,
            b.x, b.y, b.r * 1.2
          );
          glow.addColorStop(0, "#ffffff");
          glow.addColorStop(.16, b.color);
          glow.addColorStop(1, "#00000044");
          ctx.beginPath();
          ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
          ctx.fillStyle = glow;
          ctx.fill();
          ctx.strokeStyle = "#ffffff88";
          ctx.lineWidth = 1.5;
          ctx.stroke();
        }
      }

      function frame(now) {
        const elapsed = Math.min(3, (now - lastTime) / 16.6667);
        lastTime = now;
        if (playing) advance(elapsed);
        requestAnimationFrame(frame);
      }

      canvas.addEventListener("pointerdown", event => {
        const rect = canvas.getBoundingClientRect();
        addBall(
          (event.clientX - rect.left) * W / rect.width,
          (event.clientY - rect.top) * H / rect.height,
          (Math.random() - .5) * 4,
          -Math.random() * 2,
          11 + Math.random() * 10
        );
      });

      document.getElementById("drop").addEventListener("click", () => {
        addBall(W / 2 + (Math.random() - .5) * 140, 30, (Math.random() - .5) * 4, 0);
      });
      document.getElementById("play").addEventListener("click", event => {
        playing = !playing;
        event.currentTarget.textContent = playing ? "Pause" : "Play";
        lastTime = performance.now();
      });
      document.getElementById("clear").addEventListener("click", () => {
        balls.length = 0;
        draw();
      });

      window.sim = {
        w: W,
        h: H,
        balls: () => balls.map(({ x, y, vx, vy, r }) => ({ x, y, vx, vy, r })),
        addBall,
        clear: () => { balls.length = 0; draw(); },
        step: advance
      };

      draw();
      requestAnimationFrame(frame);
    })();
  </script>
</body>
</html>
